def build_linked_list(values):
    head = None
    tail = None
    for value in values:
        new_node = Node(value)
        if head is None:
            head = new_node
            tail = new_node
        else:
            tail.next = new_node
            tail = new_node
    return head

head = build_linked_list([10, 20, 30])

def find_node(head, target):
    current = head
    while current is not None:
        if current.value == target:
            return current
        current = current.next
    return None

found = find_node(head, 20)
