def delete_first(head, target):
    if head is not None and head.value == target:
        return head.next

    previous = head
    current = head.next if head is not None else None
    while current is not None:
        if current.value == target:
            previous.next = current.next
            return head
        previous = current
        current = current.next
    return head

class DoublyNode:
    def __init__(self, value):
        self.value = value
        self.prev = None
        self.next = None

class DoublyLinkedList:
    def __init__(self):
        self.head = None
        self.tail = None

def remove(self, node):
    if node.prev is None:
        self.head = node.next
    else:
        node.prev.next = node.next

    if node.next is None:
        self.tail = node.prev
    else:
        node.next.prev = node.prev

    node.prev = None
    node.next = None

DoublyLinkedList.remove = remove

def kth_from_end(head, k):
    if k <= 0:
        raise ValueError("k 必須是正整數")
    fast = head
    for _ in range(k):
        if fast is None:
            return None
        fast = fast.next

    slow = head
    while fast is not None:
        slow = slow.next
        fast = fast.next
    return slow

def has_cycle_with_set(head):
    visited = set()
    current = head
    while current is not None:
        if current in visited:
            return True
        visited.add(current)
        current = current.next
    return False

def has_cycle(head):
    slow = head
    fast = head
    while fast is not None and fast.next is not None:
        slow = slow.next
        fast = fast.next.next
        if slow is fast:
            return True
    return False

def find_cycle_entry(head):
    slow = head
    fast = head
    while fast is not None and fast.next is not None:
        slow = slow.next
        fast = fast.next.next
        if slow is fast:
            finder = head
            while finder is not slow:
                finder = finder.next
                slow = slow.next
            return finder
    return None
